import { test, expect } from '@playwright/test';

test.describe('Async Page Load Transitions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should display loading animation during async page load', async ({ page }) => {
    await page.click(getByText('Load New Content'));
    const loadingAnimation = page.getByRole('status', { name: /loading/i });
    await expect(loadingAnimation).toBeVisible();
    await expect(loadingAnimation).toBeHidden({ timeout: 5000 });
  });

  test('should display new content after loading animation', async ({ page }) => {
    await page.click(getByText('Load New Content'));
    const newContent = page.getByText('New Content Loaded');
    await expect(newContent).toBeVisible();
  });
});
